-- Affiliate catalogue enrichment for monetized ToolTrim pages.
-- Non-destructive: updates existing tools by id, inserts missing tools, then appends diagnostic cluster references.

insert into public.tools (
  id, name, slug, category, short_description, short_description_en, long_description, long_description_en,
  affiliate_link, website_url, default_monthly_price, pricing, pricing_en, pricing_v5, verdict, pros, cons,
  use_cases, covers, relevant_for, alternatives, seo, personas, tool_type, substitutable, verticals, functional_needs,
  prescription_quality, substitution_cluster_v2, decision_policy_v3, force_silence, solo_relevance, team_relevance
) values
('apollo-io', 'Apollo.io', 'apollo-io', 'communication', 'Base de prospection B2B et séquences outbound pour trouver, qualifier et contacter des leads.', 'B2B sales intelligence and outbound sequencing to find, qualify and contact leads.', 'Apollo.io réunit base de contacts B2B, enrichissement, scoring et séquences de prospection. C''est puissant pour un freelance ou une petite équipe commerciale qui veut industrialiser l''outbound, mais ToolTrim le considère comme un outil à cadrer : sans ICP clair, listes propres et volume raisonnable, le coût monte vite et la qualité commerciale baisse.', 'Apollo.io combines B2B contact data, enrichment, scoring and outbound sequences. ToolTrim sees it as useful when prospecting is already structured, not as a substitute for positioning.', 'https://get.apollo.io/i3ymfre21zro', 'https://www.apollo.io', 49, '{"free":"Plan gratuit limité selon volume.","paid":"Plans payants publics autour de l’entrée de gamme commerciale, puis tarifs plus élevés selon crédits et sièges."}'::jsonb, '{"free":"Limited free plan depending on volume.","paid":"Paid plans scale by credits, seats and sales features."}'::jsonb, '{"compare_price_monthly_eur":49,"compare_plan_name":"Basic / entry paid plan","compare_plan_kind":"paid","price_reliability":"public_pricing_or_public_entry_plan","location_sensitive":true,"usage_sensitive":true,"cautions":["Les crédits, enrichissements et sièges peuvent changer fortement le coût réel."],"source_domain":"apollo.io","official_source_url":"https://www.apollo.io/pricing","verified_on":"2026-05-03","verification_status":"verified_public_pricing_page"}'::jsonb, '{"keepIf":["Tu prospectes chaque semaine avec un ICP clair.","Tu veux enrichir et séquencer sans multiplier les outils."],"avoidIf":["Tu n’as pas encore d’offre ou de cible stable.","Tu fais moins de 20 prises de contact qualifiées par mois."],"threshold":"Rentable si la prospection génère au moins un rendez-vous qualifié supplémentaire par mois."}'::jsonb, '["Très utile pour créer une base de leads B2B qualifiée.","Combine données, enrichissement et séquences dans un seul flux.","Bon levier quand la prospection est déjà mesurée."]'::jsonb, '["Risque de payer pour du volume mal ciblé.","Peut créer du bruit commercial si le message n’est pas précis.","Nécessite une hygiène CRM stricte."]'::jsonb, '["Construire une liste de prospects B2B","Lancer des séquences outbound","Enrichir des leads avant prise de contact"]'::jsonb, '["lead-generation","sales-intelligence","outbound-email","crm-enrichment"]'::jsonb, '["consultant-b2b","fondateur-saas","business-developer"]'::jsonb, '["hubspot","pipedrive","lemlist","la-growth-machine"]'::jsonb, '{"metaDescription":"Apollo.io sur ToolTrim : prix, cas d''usage, limites et avis critique pour décider si Apollo.io mérite sa place dans ta stack."}'::jsonb, '["MARC","CLAIRE"]'::jsonb, 'gestion', true, '["consultant-b2b","fondateur-saas"]'::jsonb, '["lead-generation","sales-intelligence","outbound-email","crm-enrichment"]'::jsonb, 'question', 'crm-prospection', '{"auto_cancel_allowed":false,"auto_replace_allowed":false,"auto_downgrade_allowed":false,"requires_context_questions":true,"never_auto_cancel_reason":"Outil monétisé et contextuel : ToolTrim doit vérifier le volume, le rôle dans la stack et le risque de doublon avant recommandation.","default_decision_lane":"question"}'::jsonb, false, 'à vérifier selon volume', 'utile si usage récurrent'),
('callrail', 'CallRail', 'callrail', 'analytics', 'Call tracking, attribution marketing et analyse des appels entrants.', 'Call tracking, marketing attribution and inbound call analytics.', 'CallRail sert à comprendre quelles campagnes, pages ou mots-clés déclenchent des appels. C''est pertinent pour les activités où le téléphone est un vrai canal de conversion. Pour ToolTrim, ce n''est pas un outil de communication généraliste : c''est un outil d''attribution à activer quand les appels pèsent réellement dans le chiffre d''affaires.', 'CallRail helps attribute inbound calls to campaigns, landing pages and keywords. It is relevant when phone calls are a measurable acquisition channel.', 'https://partners.callrail.com/80aos1quxy64', 'https://www.callrail.com', 45, '{"free":"Pas de plan gratuit durable identifié.","paid":"Plan Call Tracking public à partir d’environ 45 $/mois, options et volumes en supplément."}'::jsonb, '{"free":"No durable free plan identified.","paid":"Call tracking plan starts around $45/month, with add-ons and usage depending on volume."}'::jsonb, '{"compare_price_monthly_eur":45,"compare_plan_name":"Call Tracking","compare_plan_kind":"paid","price_reliability":"public_pricing_or_public_entry_plan","location_sensitive":true,"usage_sensitive":true,"cautions":["Les numéros, minutes et options d’attribution peuvent ajouter du coût."],"source_domain":"callrail.com","official_source_url":"https://www.callrail.com/pricing/","verified_on":"2026-05-03","verification_status":"verified_public_pricing_page"}'::jsonb, '{"keepIf":["Le téléphone est un canal de vente important.","Tu dois prouver le ROI de campagnes locales ou ads."],"avoidIf":["Tu n’as presque pas d’appels entrants.","Ton acquisition est déjà suivie proprement par formulaire ou CRM."],"threshold":"À considérer dès que les appels représentent un canal mesurable, pas juste un moyen de contact."}'::jsonb, '["Relie les appels aux campagnes marketing.","Utile pour arbitrer entre SEO, ads et landing pages.","Bon outil pour les business locaux ou services à forte conversion téléphonique."]'::jsonb, '["Peu utile si les conversions se font surtout par formulaire ou paiement en ligne.","Ajoute une couche de tracking à maintenir.","Le coût dépend vite du volume de numéros et d’appels."]'::jsonb, '["Mesurer les appels générés par une campagne","Comparer landing pages et sources d’acquisition","Auditer le ROI d’un budget ads local"]'::jsonb, '["call-tracking","marketing-attribution","phone-analytics"]'::jsonb, '["consultant-b2b","agence","business-local"]'::jsonb, '["aircall-inc","krispcall"]'::jsonb, '{"metaDescription":"CallRail sur ToolTrim : prix, cas d''usage, limites et avis critique pour décider si CallRail mérite sa place dans ta stack."}'::jsonb, '["MARC","CLAIRE"]'::jsonb, 'satellite', true, '["consultant-b2b"]'::jsonb, '["call-tracking","marketing-attribution","phone-analytics"]'::jsonb, 'question', 'call-tracking', '{"auto_cancel_allowed":false,"auto_replace_allowed":false,"auto_downgrade_allowed":false,"requires_context_questions":true,"never_auto_cancel_reason":"Outil monétisé et contextuel : ToolTrim doit vérifier le volume, le rôle dans la stack et le risque de doublon avant recommandation.","default_decision_lane":"question"}'::jsonb, false, 'à vérifier selon volume', 'utile si usage récurrent'),
('dext', 'Dext', 'dext', 'finance', 'Collecte, OCR et préparation des justificatifs comptables pour cabinets et PME.', 'Receipt capture, OCR and bookkeeping preparation for accountants and SMBs.', 'Dext aide à récupérer factures, reçus et justificatifs, puis à les préparer pour la comptabilité. ToolTrim le positionne comme un outil de back-office : très utile quand les documents comptables deviennent récurrents, moins pertinent pour un solo qui peut encore gérer avec son outil de facturation et son expert-comptable.', 'Dext captures receipts and invoices, then prepares bookkeeping data. ToolTrim sees it as a back-office tool for recurring finance operations.', 'https://join.dext.com/n2kppk0g4xq5', 'https://dext.com', 0, '{"free":"Pas de prix public simple et universel identifié.","paid":"Tarif selon produit, pays, volume et cabinet comptable."}'::jsonb, '{"free":"No simple universal public price identified.","paid":"Pricing depends on product, country, volume and accounting partner."}'::jsonb, '{"compare_price_monthly_eur":0,"compare_plan_name":"Sur devis / selon produit","compare_plan_kind":"quote","price_reliability":"quote_or_location_sensitive","location_sensitive":true,"usage_sensitive":true,"cautions":["Prix dépendant du pays, du produit Dext et du volume de documents."],"source_domain":"dext.com","official_source_url":"https://dext.com/pricing","verified_on":"2026-05-03","verification_status":"public_pricing_not_universal"}'::jsonb, '{"keepIf":["Tu traites beaucoup de justificatifs chaque mois.","Ton cabinet ou ton équipe finance veut un flux plus propre."],"avoidIf":["Tu as peu de dépenses et une compta simple.","Ton outil de facturation couvre déjà le besoin."],"threshold":"Utile quand le coût administratif des justificatifs dépasse le coût logiciel."}'::jsonb, '["Réduit la friction de collecte des justificatifs.","Bon complément pour cabinets comptables et équipes finance.","Aide à fiabiliser les flux de dépenses."]'::jsonb, '["Surdimensionné si le volume de factures est faible.","Dépend de l’intégration avec l’outil comptable.","Prix difficile à comparer sans contexte."]'::jsonb, '["Collecter des reçus et factures","Préparer les pièces pour la comptabilité","Standardiser les justificatifs d’une petite équipe"]'::jsonb, '["receipt-capture","bookkeeping-prep","expense-documents"]'::jsonb, '["daf-finance","ecommercant","manager-dsi"]'::jsonb, '["quickbooks","xero","pennylane"]'::jsonb, '{"metaDescription":"Dext sur ToolTrim : prix, cas d''usage, limites et avis critique pour décider si Dext mérite sa place dans ta stack."}'::jsonb, '["CLAIRE"]'::jsonb, 'gestion', true, '["daf-finance"]'::jsonb, '["receipt-capture","bookkeeping-prep","expense-documents"]'::jsonb, 'question', 'accounting-ops', '{"auto_cancel_allowed":false,"auto_replace_allowed":false,"auto_downgrade_allowed":false,"requires_context_questions":true,"never_auto_cancel_reason":"Outil monétisé et contextuel : ToolTrim doit vérifier le volume, le rôle dans la stack et le risque de doublon avant recommandation.","default_decision_lane":"question"}'::jsonb, false, 'à vérifier selon volume', 'utile si usage récurrent'),
('aircall-inc', 'Aircall', 'aircall', 'communication', 'Téléphonie cloud pour équipes commerciales et support, intégrée au CRM.', 'Cloud phone system for sales and support teams, integrated with CRM workflows.', 'Aircall remplace la téléphonie classique par un système cloud connecté au CRM, au support et aux workflows commerciaux. ToolTrim le recommande surtout quand plusieurs personnes gèrent appels entrants, sortants et suivi client. Pour un freelance solo, l’intérêt dépend du volume d’appels et du besoin de reporting.', 'Aircall is a cloud phone system connected to CRM and support workflows. It is strongest for teams handling measurable sales or support calls.', 'https://get.aircall.io/inlxr1yjycil', 'https://aircall.io', 30, '{"free":"Pas de plan gratuit durable identifié.","paid":"Plans publics par utilisateur, souvent à partir d’environ 30 $/utilisateur/mois selon facturation."}'::jsonb, '{"free":"No durable free plan identified.","paid":"Public per-seat plans often start around $30/user/month depending on billing."}'::jsonb, '{"compare_price_monthly_eur":30,"compare_plan_name":"Essentials","compare_plan_kind":"paid_per_seat","price_reliability":"public_pricing_or_public_entry_plan","location_sensitive":true,"usage_sensitive":true,"cautions":["Prix par utilisateur ; le coût réel dépend du nombre de sièges et des options."],"source_domain":"aircall.io","official_source_url":"https://aircall.io/pricing/","verified_on":"2026-05-03","verification_status":"verified_public_pricing_page"}'::jsonb, '{"keepIf":["Plusieurs personnes prennent ou passent des appels clients.","Tu veux connecter téléphone et CRM."],"avoidIf":["Tu utilises peu le téléphone.","Un simple numéro pro suffit."],"threshold":"Pertinent si les appels sont un vrai workflow, pas seulement un canal ponctuel."}'::jsonb, '["Très bon pour relier appels, CRM et support.","Plus lisible qu’un téléphone dispersé entre plusieurs numéros.","Adapté aux équipes sales/support."]'::jsonb, '["Trop lourd pour peu d’appels.","Coût par siège à surveiller.","Demande une discipline CRM pour produire de la valeur."]'::jsonb, '["Gérer une ligne commerciale partagée","Suivre les appels dans un CRM","Structurer un support téléphonique"]'::jsonb, '["business-phone","call-center","crm-calls"]'::jsonb, '["consultant-b2b","fondateur-saas","manager-dsi"]'::jsonb, '["krispcall","callrail"]'::jsonb, '{"metaDescription":"Aircall sur ToolTrim : prix, cas d''usage, limites et avis critique pour décider si Aircall mérite sa place dans ta stack."}'::jsonb, '["MARC","CLAIRE"]'::jsonb, 'gestion', true, '["consultant-b2b","fondateur-saas"]'::jsonb, '["business-phone","call-center","crm-calls"]'::jsonb, 'question', 'business-phone', '{"auto_cancel_allowed":false,"auto_replace_allowed":false,"auto_downgrade_allowed":false,"requires_context_questions":true,"never_auto_cancel_reason":"Outil monétisé et contextuel : ToolTrim doit vérifier le volume, le rôle dans la stack et le risque de doublon avant recommandation.","default_decision_lane":"question"}'::jsonb, false, 'à vérifier selon volume', 'utile si usage récurrent'),
('buddy-punch', 'Buddy Punch', 'buddy-punch', 'productivity-tracking', 'Suivi du temps, pointage et planification pour petites équipes.', 'Time clock, scheduling and attendance tracking for small teams.', 'Buddy Punch sert à suivre les heures, présences, pauses et plannings. Pour ToolTrim, c''est un outil RH opérationnel : utile quand il y a une équipe à coordonner, rarement prioritaire pour un freelance solo qui veut juste suivre son temps projet.', 'Buddy Punch tracks attendance, time clocks and schedules. ToolTrim sees it as an operational HR tool for teams.', 'https://try.buddypunch.com/6oeemql0j0q3', 'https://buddypunch.com', 24, '{"free":"Essai gratuit selon offre.","paid":"Tarif public composé d’un abonnement de base et/ou prix par utilisateur selon plan."}'::jsonb, '{"free":"Free trial depending on offer.","paid":"Public pricing usually combines base fee and per-user pricing depending on plan."}'::jsonb, '{"compare_price_monthly_eur":24,"compare_plan_name":"Entry team setup","compare_plan_kind":"paid_per_seat","price_reliability":"public_pricing_or_public_entry_plan","location_sensitive":true,"usage_sensitive":true,"cautions":["Comparer le coût total avec base fee + utilisateurs, pas seulement le prix par personne."],"source_domain":"buddypunch.com","official_source_url":"https://buddypunch.com/pricing/","verified_on":"2026-05-03","verification_status":"verified_public_pricing_page"}'::jsonb, '{"keepIf":["Tu dois suivre présence et heures d’une équipe.","Les feuilles d’heures deviennent une source d’erreur."],"avoidIf":["Tu veux juste tracker ton temps freelance.","Tu n’as pas de salariés ou prestataires à pointer."],"threshold":"Utile quand le suivi RH évite erreurs de paie ou de planning."}'::jsonb, '["Simple pour encadrer pointage et présence.","Adapté aux petites équipes terrain ou support.","Réduit les feuilles d’heures dispersées."]'::jsonb, '["Peu utile pour un solo sans salariés.","N’est pas un vrai outil de pilotage projet.","Le coût dépend du nombre d’utilisateurs."]'::jsonb, '["Pointer les heures d’une équipe","Gérer absences et plannings","Préparer des données de paie"]'::jsonb, '["time-clock","attendance","employee-scheduling"]'::jsonb, '["manager-dsi","daf-finance"]'::jsonb, '["toggl-track","clockify","trainual"]'::jsonb, '{"metaDescription":"Buddy Punch sur ToolTrim : prix, cas d''usage, limites et avis critique pour décider si Buddy Punch mérite sa place dans ta stack."}'::jsonb, '["CLAIRE"]'::jsonb, 'gestion', true, '["manager-dsi"]'::jsonb, '["time-clock","attendance","employee-scheduling"]'::jsonb, 'question', 'hr-time-tracking', '{"auto_cancel_allowed":false,"auto_replace_allowed":false,"auto_downgrade_allowed":false,"requires_context_questions":true,"never_auto_cancel_reason":"Outil monétisé et contextuel : ToolTrim doit vérifier le volume, le rôle dans la stack et le risque de doublon avant recommandation.","default_decision_lane":"question"}'::jsonb, false, 'à vérifier selon volume', 'utile si usage récurrent'),
('leadpages', 'Leadpages', 'leadpages', 'nocode-web', 'Création de landing pages, pop-ups et formulaires orientés conversion.', 'Landing pages, pop-ups and forms built for conversion.', 'Leadpages est un constructeur de pages d’atterrissage pensé pour la conversion plus que pour le design complet d’un site. ToolTrim le classe comme utile quand tu testes des offres, pages ads ou magnets. Si ton site est déjà bien tenu sur Webflow, Framer ou WordPress, il faut éviter la surcouche inutile.', 'Leadpages is a conversion-focused landing page builder. ToolTrim recommends it for offer tests and acquisition pages, not as another layer on top of an already solid website.', 'https://try.leadpages.com/dzadrshoyk4d', 'https://www.leadpages.com', 37, '{"free":"Essai gratuit selon période commerciale.","paid":"Plans publics à partir d’environ 37 $/mois en facturation annuelle, plus en mensuel."}'::jsonb, '{"free":"Free trial depending on current offer.","paid":"Public plans start around $37/month billed annually, higher monthly."}'::jsonb, '{"compare_price_monthly_eur":37,"compare_plan_name":"Standard","compare_plan_kind":"paid","price_reliability":"public_pricing_or_public_entry_plan","location_sensitive":true,"usage_sensitive":false,"cautions":["Comparer avec ton CMS actuel : le doublon avec Webflow, Framer ou WordPress est fréquent."],"source_domain":"leadpages.com","official_source_url":"https://www.leadpages.com/pricing","verified_on":"2026-05-03","verification_status":"verified_public_pricing_page"}'::jsonb, '{"keepIf":["Tu testes souvent des offres ou pages de campagne.","Tu veux capter des leads sans mobiliser un développeur."],"avoidIf":["Ton site actuel permet déjà de publier vite.","Tu n’as pas encore de trafic qualifié."],"threshold":"Rentable si la page sert une campagne mesurée, pas une simple envie de landing page."}'::jsonb, '["Rapide pour tester une offre.","Bon focus conversion formulaire / lead magnet.","Moins lourd qu’un projet site complet."]'::jsonb, '["Peut faire doublon avec un CMS déjà solide.","Moins flexible qu’un vrai système web.","Coût difficile à justifier sans trafic ou campagne."]'::jsonb, '["Créer une page de capture","Tester une offre avant refonte site","Lancer une campagne ads"]'::jsonb, '["landing-page-builder","lead-capture","conversion-testing"]'::jsonb, '["consultant-b2b","createur-contenu","fondateur-saas"]'::jsonb, '["webflow","framer","wordpress-com"]'::jsonb, '{"metaDescription":"Leadpages sur ToolTrim : prix, cas d''usage, limites et avis critique pour décider si Leadpages mérite sa place dans ta stack."}'::jsonb, '["MARC","ALIX"]'::jsonb, 'satellite', true, '["consultant-b2b","createur-contenu"]'::jsonb, '["landing-page-builder","lead-capture","conversion-testing"]'::jsonb, 'question', 'landing-page-builder', '{"auto_cancel_allowed":false,"auto_replace_allowed":false,"auto_downgrade_allowed":false,"requires_context_questions":true,"never_auto_cancel_reason":"Outil monétisé et contextuel : ToolTrim doit vérifier le volume, le rôle dans la stack et le risque de doublon avant recommandation.","default_decision_lane":"question"}'::jsonb, false, 'à vérifier selon volume', 'utile si usage récurrent'),
('deel', 'Deel', 'deel', 'hris-payroll', 'Contrats, paie internationale, EOR et gestion de collaborateurs distribués.', 'Contracts, global payroll, EOR and distributed workforce management.', 'Deel aide à contractualiser, payer et gérer des collaborateurs ou prestataires dans plusieurs pays. Pour ToolTrim, c’est pertinent dès que le sujet légal/RH dépasse la simple facture freelance. En dessous, il peut être trop structurant et coûteux.', 'Deel helps manage contractors, global payroll and EOR workflows. ToolTrim sees it as useful when international hiring becomes operationally risky.', 'https://get.deel.com/hftlk37l5raa', 'https://www.deel.com', 49, '{"free":"Certains modules RH peuvent être gratuits ou inclus selon offre.","paid":"Deel Contractor Management affiché à partir d’environ 49 $/mois ; EOR, Payroll et modules avancés sur devis."}'::jsonb, '{"free":"Some HR modules may be free or included depending on offer.","paid":"Contractor Management starts around $49/month; EOR, Payroll and advanced modules are quote-based."}'::jsonb, '{"compare_price_monthly_eur":49,"compare_plan_name":"Contractor Management","compare_plan_kind":"paid","price_reliability":"public_pricing_or_public_entry_plan","location_sensitive":true,"usage_sensitive":true,"cautions":["Le coût varie fortement entre contractor, EOR, payroll et pays concernés."],"source_domain":"deel.com","official_source_url":"https://www.deel.com/pricing","verified_on":"2026-05-03","verification_status":"verified_public_pricing_page"}'::jsonb, '{"keepIf":["Tu travailles avec des prestataires ou salariés dans plusieurs pays.","La conformité RH devient un vrai risque."],"avoidIf":["Tu paies quelques freelances locaux par facture.","Tu n’as pas de sujet international."],"threshold":"À considérer dès que le coût du risque légal dépasse le coût de la plateforme."}'::jsonb, '["Très utile pour gérer des prestataires internationaux.","Réduit le risque administratif et contractuel.","Centralise documents, paiements et conformité."]'::jsonb, '["Surdimensionné pour une équipe locale simple.","Les modules avancés peuvent coûter cher.","Dépend fortement des pays et statuts."]'::jsonb, '["Payer des contractors internationaux","Gérer contrats et conformité pays","Structurer une équipe distribuée"]'::jsonb, '["global-payroll","contractor-management","hr-compliance"]'::jsonb, '["manager-dsi","fondateur-saas","daf-finance"]'::jsonb, '["remote","rippling","bamboohr"]'::jsonb, '{"metaDescription":"Deel sur ToolTrim : prix, cas d''usage, limites et avis critique pour décider si Deel mérite sa place dans ta stack."}'::jsonb, '["CLAIRE"]'::jsonb, 'gestion', true, '["manager-dsi","fondateur-saas"]'::jsonb, '["global-payroll","contractor-management","hr-compliance"]'::jsonb, 'question', 'hris-payroll', '{"auto_cancel_allowed":false,"auto_replace_allowed":false,"auto_downgrade_allowed":false,"requires_context_questions":true,"never_auto_cancel_reason":"Outil monétisé et contextuel : ToolTrim doit vérifier le volume, le rôle dans la stack et le risque de doublon avant recommandation.","default_decision_lane":"question"}'::jsonb, false, 'à vérifier selon volume', 'utile si usage récurrent'),
('lemlist', 'Lemlist', 'lemlist', 'email-productivity', 'Séquences d’email outbound et prospection multicanale personnalisée.', 'Outbound email sequences and personalized multichannel prospecting.', 'Lemlist aide à envoyer des séquences de prospection personnalisées et à suivre les réponses. ToolTrim le voit comme un outil de vente, pas d’email marketing généraliste. Il devient utile quand l’offre, la cible et le rythme de prospection sont déjà clairs.', 'Lemlist is for personalized outbound sequences, not general newsletter marketing. It is valuable when positioning and prospecting rhythm are clear.', 'https://get.lemlist.com/iqofb24egwan', 'https://www.lemlist.com', 39, '{"free":"Pas de plan gratuit durable identifié.","paid":"Plans publics à partir d’environ 39 $/mois selon fonctionnalités."}'::jsonb, '{"free":"No durable free plan identified.","paid":"Public plans start around $39/month depending on features."}'::jsonb, '{"compare_price_monthly_eur":39,"compare_plan_name":"Email Starter","compare_plan_kind":"paid","price_reliability":"public_pricing_or_public_entry_plan","location_sensitive":true,"usage_sensitive":true,"cautions":[],"source_domain":"lemlist.com","official_source_url":"https://www.lemlist.com/pricing","verified_on":"2026-05-03","verification_status":"verified_public_pricing_page"}'::jsonb, '{"keepIf":["Tu fais de la prospection B2B chaque semaine.","Tu as besoin de séquences personnalisées."],"avoidIf":["Tu veux envoyer une newsletter.","Tu n’as pas encore validé ton message commercial."],"threshold":"Rentable si chaque campagne est reliée à un pipeline mesuré."}'::jsonb, '["Bon pour structurer une prospection régulière.","Personnalisation plus avancée qu’un outil emailing classique.","Adapté aux consultants et commerciaux B2B."]'::jsonb, '["Peut nuire à la délivrabilité si mal utilisé.","Ne remplace pas une offre claire.","Doublonne vite avec Apollo ou un CRM si mal cadré."]'::jsonb, '["Créer des séquences outbound","Relancer des prospects B2B","Suivre réponses et rendez-vous"]'::jsonb, '["outbound-email","sales-sequences","prospecting-followup"]'::jsonb, '["consultant-b2b","fondateur-saas"]'::jsonb, '["apollo-io","la-growth-machine","activecampaign"]'::jsonb, '{"metaDescription":"Lemlist sur ToolTrim : prix, cas d''usage, limites et avis critique pour décider si Lemlist mérite sa place dans ta stack."}'::jsonb, '["MARC"]'::jsonb, 'satellite', true, '["consultant-b2b"]'::jsonb, '["outbound-email","sales-sequences","prospecting-followup"]'::jsonb, 'question', 'outbound-email', '{"auto_cancel_allowed":false,"auto_replace_allowed":false,"auto_downgrade_allowed":false,"requires_context_questions":true,"never_auto_cancel_reason":"Outil monétisé et contextuel : ToolTrim doit vérifier le volume, le rôle dans la stack et le risque de doublon avant recommandation.","default_decision_lane":"question"}'::jsonb, false, 'à vérifier selon volume', 'utile si usage récurrent'),
('brevo', 'Brevo', 'brevo', 'email-productivity', 'Email marketing, automation, SMS et CRM léger pour PME.', 'Email marketing, automation, SMS and lightweight CRM for SMBs.', 'Brevo est une suite marketing accessible pour newsletters, automatisations, SMS et CRM léger. ToolTrim l’apprécie quand il faut un outil robuste sans prix enterprise, mais recommande de vérifier le volume d’emails et le besoin réel d’automation avant d’empiler avec un CRM ou une plateforme newsletter.', 'Brevo is an accessible marketing suite for newsletters, automation, SMS and lightweight CRM. ToolTrim likes it when email volume and automation needs are real.', 'https://get.brevo.com/k11w0iqmh2r0-m7y3c', 'https://www.brevo.com', 9, '{"free":"Plan gratuit limité en volume quotidien.","paid":"Plans publics à partir d’environ 9 €/mois selon volume et fonctionnalités."}'::jsonb, '{"free":"Free plan with daily send limits.","paid":"Public plans start around €9/month depending on volume and features."}'::jsonb, '{"compare_price_monthly_eur":9,"compare_plan_name":"Starter","compare_plan_kind":"paid","price_reliability":"public_pricing_or_public_entry_plan","location_sensitive":true,"usage_sensitive":true,"cautions":["Le prix dépend surtout du volume d’emails et des options marketing."],"source_domain":"brevo.com","official_source_url":"https://www.brevo.com/pricing/","verified_on":"2026-05-03","verification_status":"verified_public_pricing_page"}'::jsonb, '{"keepIf":["Tu veux email + automation sans budget lourd.","Tu as besoin d’un outil marketing généraliste."],"avoidIf":["Tu écris uniquement une newsletter éditoriale simple.","Tu as déjà un CRM marketing complet."],"threshold":"Bon choix si l’automation sert vraiment la conversion, pas juste l’accumulation."}'::jsonb, '["Bon rapport fonctionnalité/prix pour newsletters et automation.","Plan gratuit utile pour démarrer.","Peut remplacer plusieurs petits outils marketing."]'::jsonb, '["Interface moins spécialisée qu’un outil créateur comme Kit.","