on conflict (id) do update set
  name = excluded.name,
  slug = excluded.slug,
  category = excluded.category,
  short_description = excluded.short_description,
  short_description_en = excluded.short_description_en,
  long_description = excluded.long_description,
  long_description_en = excluded.long_description_en,
  affiliate_link = excluded.affiliate_link,
  website_url = excluded.website_url,
  default_monthly_price = excluded.default_monthly_price,
  pricing = excluded.pricing,
  pricing_en = excluded.pricing_en,
  pricing_v5 = excluded.pricing_v5,
  verdict = excluded.verdict,
  pros = excluded.pros,
  cons = excluded.cons,
  use_cases = excluded.use_cases,
  covers = excluded.covers,
  relevant_for = excluded.relevant_for,
  alternatives = excluded.alternatives,
  seo = excluded.seo,
  personas = excluded.personas,
  tool_type = excluded.tool_type,
  substitutable = excluded.substitutable,
  verticals = excluded.verticals,
  functional_needs = excluded.functional_needs,
  prescription_quality = excluded.prescription_quality,
