with additions(cluster_id, ids) as (
  values
('marc-1', '["apollo-io","activecampaign"]'::jsonb),
('marc-prospection', '["apollo-io","lemlist"]'::jsonb),
('marc-7', '["brevo","convertkit","lemlist","activecampaign"]'::jsonb),
('marc-5', '["aircall-inc","krispcall","callrail"]'::jsonb),
('alix-2', '["brevo","convertkit","activecampaign"]'::jsonb),
('alix-3', '["socialbee"]'::jsonb),
('alix-6', '["hume-ai"]'::jsonb),
('alix-8', '["leadpages"]'::jsonb),
('claire-1', '["dext"]'::jsonb),
('claire-4', '["aircall-inc","krispcall","callrail"]'::jsonb),
('claire-7', '["deel","buddy-punch","trainual"]'::jsonb),
('claire-hr', '["deel","buddy-punch","trainual"]'::jsonb),
('sofia-6', '["hume-ai"]'::jsonb),
('theo-devtools', '["hume-ai"]'::jsonb)
), expanded as (
  select c.id, jsonb_agg(distinct tool_id.value order by tool_id.value) as merged_ids
  from public.clusters c
  join additions a on a.cluster_id = c.id
  cross join lateral jsonb_array_elements_text(coalesce(c.tool_ids, '[]'::jsonb) || a.ids) as tool_id(value)
  group by c.id
)
update public.clusters c
set tool_ids = expanded.merged_ids
from expanded
where c.id = expanded.id;

insert into public.clusters (id, persona, "order", question, question_en, why, cols, tool_ids) values
  ('theo-data-proxies', 'THEO', 14, 'Tes outils proxy et collecte de données web', 'Your proxy and web data collection tools', 'À n’utiliser que pour des cas data encadrés : coût, conformité et maintenance peuvent vite dépasser le gain.', 2, '["thordata"]'::jsonb)
